              "id": "MI-TE-EVM-02",
              "text": "(나) 평가 내용이나 방법에 따라 다양한 디지털 도구(프로그램 자동 평가시스템, 학습관리시스템(LMS) 등)를 활용할 수 있으며, 평가 이전에 학생이 디지털 도구를 다룰 수 있도록 교육하여 평가의 불이익이 없도록 계획한다.",
