              "text": "알고리즘을 적용한 프로그램의 평가 시 알고리즘의 효과성과 효율성을 종합적으로 평가하도록 한다. 특히 다양한 프로그램 환경이나 데이터를 활용하여 설계한 알고리즘이 동일하게 효율적으로 작동하는지를 평가하여 학습 내용이 확장·전이되었는지를 확인하도록 한다.",
