              "text": "(다) 알고리즘을 평가할 때 가능하면 프로그램 자동 평가시스템을 활용하여 컴퓨팅 시스템에서 실제로 구현되는 결과를 평가하도록 하며, 해당 방법을 활용하기 어려운 경우 대표성을 지니는 데이터를 선정하여 평가 문항과 루브릭을 구성하고, 지필평가나 수행평가의 형태로 평가를 진행하여 공정한 평가가 되도록 한다.",
