              "text": "[12정03-01] 복잡한 문제를 분석하는 단계에서 좀 더 작은 문제로 분해하는 과정을 수행하며 해결하기 용이하도록 단순화나 구조화하는 모델링 단계를 수행할 수 있어야 한다. 작은 문제의 해결 결과를 종합하는 과정에서 작은 문제를 모두 수행했을 때 전체 문제 해결이 원활하게 이루어지는지, 오류가 없는지를 확인할 수 있어야 한다.",
