              "text": "인공지능의 다양한 사례를 탐색하여 실제로 많은 분야에 인공지능이 활용되고 있음을 인식하고 인공지능을 구현하는 방법으로서 탐색과 추론 방식에 대한 이해를 바탕으로 문제를 해결할 수 있는 능력을 함양하도록 교수·학습을 계획한다. 특히 탐색 방식으로 문제를 해결하는 과정에서는 탐색 알고리즘을 적용한 프로그램을 개발하는 방식으로 활동을 구성하도록 한다.",
