              "text": "[12인기03-03] 인공지능에 대한 일방적인 수용 또는 거부보다는 비판적인 자세를 바탕으로 인간과 공존해야 하는 존재로서 인공지능의 역할을 제시할 수 있어야 한다. 인공지능을 대하는 인간의 태도에 대한 윤리적 고찰을 통해 바람직한 공존 방식을 규정할 수 있어야 한다.",
