              "text": "‘인공지능 기초’는 학문의 분야 중 컴퓨터과학, 데이터 과학, 정보시스템의 내용을 기반으로, 개인의 삶과 다양한 분야에서 직접적인 영향을 미치고 있는 인공지능에 대한 깊은 이해를 제공하게 된다.",
