              "text": "‘인공지능 기초’는 인공지능의 발전에 따른 사회의 변화를 파악하고, 인공지능의 원리에 대한 이해를 바탕으로 인공지능을 다양한 분야의 문제를 창의적으로 해결하기 위한 핵심 도구로서 프로그래밍할 수 있으며, 인공지능의 윤리적 쟁점에 관한 올바른 가치관과 태도를 함양하는 데 중점을 둔다.",
