              "text": "(다) 학습자의 디지털·인공지능 소양에 대해 선제적으로 파악하고 학생의 현재 수준에 맞는 방식으로 교수·학습 활동을 구성한다. 프로그래밍을 통한 인공지능 프로그램의 개발 활동을 중심으로 하되, 인공지능 개념 이해에 도움이 되는 소프트웨어나 인공지능 관련 라이브러리를 적극적으로 활용하여 최소 성취수준을 보장하도록 한다.",
