              "text": "(다) 인공지능에 관련된 평가는 다양한 방식으로 나타날 수 있으므로 정량적 평가와 정성적 평가 내용을 명확하게 구분한다. 특히 모델 학습과 적용이 반복적으로 이루어지는 프로젝트의 경우 평가 결과가 학생 활동에 즉시 피드백되어 결과물의 개선으로 나타날 수 있도록 평가를 계획한다.",
