              "text": "(마) ‘소프트웨어와 생활’ 과목의 교수·학습에서는 교과 간, 교과 내 영역 간의 연계성을 고려하여 학습 경험을 조직함으로써 융합적 사고력을 함양할 수 있도록 하며, 융합적 문제 해결이 단편적인 경험을 넘어 의미 있는 문제 해결이 되도록 함으로써 삶 속에서 학습의 전이가 일어날 수 있도록 한다.",
